use base64::{engine::general_purpose::URL_SAFE_NO_PAD, Engine};
use sha2::{Digest, Sha256};

/// One authorization attempt. Neither value should be logged or persisted.
pub struct AuthorizationAttempt {
    verifier: String,
    state: String,
}

impl AuthorizationAttempt {
    pub fn new() -> Self {
        // UUID v4 is generated by the OS cryptographic RNG. Two independent
        // values provide 244 random bits after UUID version and variant bits.
        let mut bytes = [0u8; 32];
        bytes[..16].copy_from_slice(uuid::Uuid::new_v4().as_bytes());
        bytes[16..].copy_from_slice(uuid::Uuid::new_v4().as_bytes());
        Self {
            verifier: URL_SAFE_NO_PAD.encode(bytes),
            state: URL_SAFE_NO_PAD.encode(uuid::Uuid::new_v4().as_bytes()),
        }
    }

    pub fn challenge(&self) -> String {
        URL_SAFE_NO_PAD.encode(Sha256::digest(self.verifier.as_bytes()))
    }

    pub fn verifier(&self) -> &str {
        &self.verifier
    }
    pub fn state(&self) -> &str {
        &self.state
    }

    /// Accept only a single state and code from the expected loopback callback.
    pub fn callback_code(
        &self,
        callback: &str,
        expected: &reqwest::Url,
    ) -> Result<String, &'static str> {
        let url = reqwest::Url::parse(callback).map_err(|_| "Invalid callback URL")?;
        if url.scheme() != "http"
            || url.host_str() != Some("localhost")
            || url.host_str() != expected.host_str()
            || url.port_or_known_default() != expected.port_or_known_default()
            || url.path() != expected.path()
            || !url.username().is_empty()
            || url.password().is_some()
            || url.fragment().is_some()
        {
            return Err("Unexpected authorization callback");
        }
        let mut state = None;
        let mut code = None;
        for (key, value) in url.query_pairs() {
            match key.as_ref() {
                "state" if state.is_none() => state = Some(value.into_owned()),
                "code" if code.is_none() => code = Some(value.into_owned()),
                "state" | "code" => return Err("Duplicate authorization parameter"),
                "error" => return Err("Microsoft authorization was declined or failed"),
                _ => {}
            }
        }
        if state.as_deref() != Some(self.state()) {
            return Err("Authorization state did not match");
        }
        match code {
            Some(code) if !code.is_empty() && code.len() <= 8192 => Ok(code),
            _ => Err("Authorization code missing or invalid"),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn pkce_matches_rfc_7636_example() {
        let attempt = AuthorizationAttempt {
            verifier: "dBjftJeZ4CVP-mB92K27uhbUJU1p1r_wW1gFWFOEjXk".into(),
            state: "state".into(),
        };
        assert_eq!(
            attempt.challenge(),
            "E9Melhoa2OwvFrEMTJguCHaoeK1t8URWbuGJSstw-cM"
        );
    }

    #[test]
    fn callbacks_require_matching_origin_and_unique_state() {
        let attempt = AuthorizationAttempt::new();
        let expected = reqwest::Url::parse("http://localhost:4123/callback").unwrap();
        let good = format!(
            "http://localhost:4123/callback?code=abc&state={}",
            attempt.state()
        );
        assert_eq!(attempt.callback_code(&good, &expected).unwrap(), "abc");
        assert!(attempt
            .callback_code(&good.replace("4123", "4124"), &expected)
            .is_err());
        assert!(attempt
            .callback_code(&format!("{good}&state=other"), &expected)
            .is_err());
        assert!(attempt
            .callback_code(
                "http://localhost:4123/callback?code=abc&state=wrong",
                &expected
            )
            .is_err());
        assert_ne!(attempt.verifier(), AuthorizationAttempt::new().verifier());
    }
}
